cell.wizd:
{布林·突破中轨} INPUT:N(10,3,100,1),P(3,2,100,1),M(6,1,21);
AA:=(((CAPITAL/1000000)<=11) AND RANGE(DYNAINFO(7),6.0,96));
ST:=(STRFIND(STKNAME,'S',1)>0 OR STRFIND(STKNAME,'*S',2)>0);
TP:=DYNAINFO(4)=0;B:=INBLOCK('房地产') OR INBLOCK('银行类');
KF:=(O-REF(C,1))/REF(C,1)*100;ZFB:=BETWEEN(KF,1.96,-2.35)=1;
YZB:=(CLOSE/REF(CLOSE,1)>1.0975 AND HIGH=OPEN AND LOW=HIGH);
AAA:=(AA AND (NOT(ST) AND NOT(TP) AND NOT(YZB) AND NOT(B)));
BBI:=(MA(CLOSE,3)+MA(CLOSE,6)+MA(CLOSE,12)+ MA(CLOSE,24))/4;
UPR:=(BBI+P*STD(BBI,N));  DWN:=(BBI-P*STD(BBI,N));
JDA:=(ATAN((UPR/REF(UPR,1)-1)*100)*180/3.1415926);
JDB:=(ATAN((BBI/REF(BBI,1)-1)*100)*180/3.1415926);
ZDA:=(CLOSE-REF(CLOSE,1))/REF(CLOSE,1)*100;
ZFA:=((HIGH-LOW)/REF(C,1)*100>=7 AND C>=O);
LRZF:=(C-REF(CLOSE,2))/REF(CLOSE,2)*100>=1;
LRDF:=(HHV(CLOSE,8)-CLOSE)/CLOSE *100<=4.2;
NSG:=IF(DYNAINFO(4)>0,(ANY(LRZF,6) AND LRDF),0);QXG:=(BARSCOUNT(C)>69);
ZTG:=IF((C-REF(C,1))*100/REF(C,1)>=(10-0.01*100/REF(C,1)) AND C=H,1,0);
IF((AAA AND ZFB AND QXG AND NSG AND ANY(ZTG,21)>=1),((JDA>9 AND JDB>0) 
AND (ANY((ZDA>1 AND CLOSE>=BBI),M) OR ANY((ZFA>0 AND LOW>=BBI),M))),0);

{日线·限幅
TT:=(DYNAINFO(9)>=CAPITAL*0.0008);
LRZF:=(C-REF(CLOSE,2))/REF(CLOSE,2)*100>0;
LRDF:=(HHV(CLOSE,8)-CLOSE)/CLOSE *100<4.0;
KF:=(O-REF(C,1))/REF(C,1)*100; ZF:=BETWEEN(KF,2.08,-3.69)=1;
AA:=(((CAPITAL/1000000)<=11) AND RANGE(DYNAINFO(7),6.0,96));
ST:=(STRFIND(STKNAME,'S',1)>0 OR STRFIND(STKNAME,'*S',2)>0);
TP:=DYNAINFO(4)=0;B:=INBLOCK('房地产') OR INBLOCK('银行类');
YZB:=(CLOSE/REF(CLOSE,1)>1.0975 AND HIGH=OPEN AND LOW=HIGH);
AAA:=(AA AND (NOT(ST) AND NOT(TP) AND NOT(YZB) AND NOT(B)));
BXYLCQGZSJ:AAA AND IF((ANY(LRZF,6) AND LRDF),IF(ZF,TT,0),0);}

{日线·限幅}
TT:=(DYNAINFO(9)>=CAPITAL*0.0001);
LRZF:=(C-REF(CLOSE,2))/REF(CLOSE,2)*100>0;
LRDF:=(HHV(CLOSE,8)-CLOSE)/CLOSE *100<4.0;
KF:=(O-REF(C,1))/REF(C,1)*100; ZF:=BETWEEN(KF,2.08,-3.69)=1;
AA:=(((CAPITAL/1000000)<=11) AND RANGE(DYNAINFO(7),6.0,96));
ST:=(STRFIND(STKNAME,'S',1)>0 OR STRFIND(STKNAME,'*S',2)>0);
TP:=DYNAINFO(4)=0;B:=INBLOCK('房地产') OR INBLOCK('银行类');
YZB:=(CLOSE/REF(CLOSE,1)>1.0975 AND HIGH=OPEN AND LOW=HIGH);
AAA:=(AA AND (NOT(ST) AND NOT(TP) AND NOT(YZB) AND NOT(B)));
BXYLCQGZSJ:AAA AND IF((ANY(LRZF,6) AND LRDF),IF(ZF,TT,0),0);

{竞价·风险控制}    BKZD:=
SUM(DYNAINFO(25),1)+SUM(DYNAINFO(26),1)+
SUM(DYNAINFO(27),1)+SUM(DYNAINFO(41),1)+
SUM(DYNAINFO(48),1);
FK:=(DYNAINFO(16)/(CAPITAL/1000000))
 * (DYNAINFO(8) * 1000/DYNAINFO(38));
FKQS:IF(SUM(BKZD/5,1)/CAPITAL*100,FK,0);

{日线·刑正一刀
S:=IF(H=L,SGN(REF(C,1)-C),(H-MAX(C,O))/(H-L));
B:=IF(H=L,SGN(REF(C,1)-C),(MIN(C,O)-L)/(H-L));
a1:=S*V; a2:=B*V;
IF(REF(a1,1)/REF(MA(a2,3),2)>0,REF(C,1)/O,00);}

{日线·力度·主力排序 a1:=DYNAINFO(17);
a2:=DYNAINFO(14)*100;a3:="DDY.DDY#DAY";
ZD:=(a3*a1)*10+(a2*a1)*10+(a1*38)*1.58;
BXYLCQGZSJ:(IF(DYNAINFO(15)>0,(ZD),0));}
